def test_load_flow_to_domain_follows_registry_edits(tmp_path: Path) -> None:
    'AC-testing.benchmarks.4'; from common.testing.benchmarks.case_types import load_flow_to_domain; registry = {'domains': [{'id': 2, 'flows': [{'id': 3}]}, {'id': 1, 'flows': [{'id': 1}, {'id': 2}]}]}; path = tmp_path / 'flows.json'; path.write_text(json.dumps(registry), encoding='utf-8'); assert load_flow_to_domain(path) == {3: 2, 1: 1, 2: 1}; registry['domains'][0]['flows'].append({'id': 4}); path.write_text(json.dumps(registry), encoding='utf-8'); assert load_flow_to_domain(path) == {3: 2, 4: 2, 1: 1, 2: 1}; 'AC-testing.benchmarks.4'; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); 'AC-testing.benchmarks.4'; from common.testing.benchmarks.case_types import load_flow_to_cases; _m2_registry = {'domains': [{'id': 2, 'flows': [{'id': 3, 'benchmark_cases': ['2']}]}, {'id': 1, 'flows': [{'id': 1, 'benchmark_cases': ['1']}, {'id': 2, 'benchmark_cases': ['1', '6']}]}]}; _m2_path = _m2_tmp / 'flows.json'; _m2_path.write_text(json.dumps(_m2_registry), encoding='utf-8'); assert load_flow_to_cases(_m2_path) == {3: ['2'], 1: ['1'], 2: ['1', '6']}; 'AC-testing.benchmarks.4'; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); 'AC-testing.benchmarks.4'; from common.testing.benchmarks.case_types import load_flow_to_cases; _m3_path = _m3_tmp / 'nonexistent.json'
    with pytest.raises(ValueError, match='30-flow registry .*nonexistent.json'): load_flow_to_cases(_m3_path)
